-- Sahafi Colony Portal — one-time data migration from the community's Excel records
--
-- Run this in the Supabase SQL Editor AFTER schema.sql has been applied.
--
-- Sources:
--   - Sahafi_Colony_E_Block_Monthly_Accounts.xlsx: a single-period snapshot of all
--     130 houses (Paid/Pending + amount), and 5 real entries in its Expense Log sheet.
--     The sheet carries no date/period of its own; per the project owner, this
--     snapshot represents September 2026.
--   - for_work_E_block_list.xlsx, sheet "shafi catalogue e block": 31 residents who've
--     shared name/occupation/blood group. Its other three tabs (personal loan notes,
--     a wedding budget) are unrelated to the community fund and were not imported.
--
-- Safe to re-run: residents upsert by (block, house_number); collections/expenses
-- rows are only inserted if an identical row doesn't already exist.

-- ============================================================================
-- Residents directory: 130 houses (4 of them vacant plots: E-81–E-84),
-- enriched with name/occupation/blood group for the 30 houses in the catalogue.
-- ============================================================================

Assistant Registrar, Lahore High Court', 'B-', false) on conflict (block, house_number) do update set name = coalesce(excluded.name, public.residents.name), occupation = coalesce(excluded.occupation, public.residents.occupation), blood_group = coalesce(excluded.blood_group, public.residents.blood_group), is_vacant = excluded.is_vacant, updated_at = now();
President Association photo journalist of Lahore', 'B+', false) on conflict (block, house_number) do update set name = coalesce(excluded.name, public.residents.name), occupation = coalesce(excluded.occupation, public.residents.occupation), blood_group = coalesce(excluded.blood_group, public.residents.blood_group), is_vacant = excluded.is_vacant, updated_at = now();

-- ============================================================================
-- Collections: 50 houses marked "Paid" in the snapshot — imported as
-- September 2026 (period_month=9, period_year=2026). recorded_by is left null
-- (nobody in the app recorded these — they're an import from the Excel ledger).
-- ============================================================================


